package ama.transcript;
import ama.contract.MinutesContracts.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
/** Detached graph algorithm test. No graph from here is passed to a write/authority gate. */
public final class Task09Fix01GraphProbe {
 public static void verify(MinutesExternalPreparation.Request request,byte[] bytes){var graph=request.input.snapshot().graph();var binding=request.input.binding();var output=new ama.minutes.json.StrictMinutesJsonReader().read(new java.io.ByteArrayInputStream(bytes),new ValidationContext(binding.fingerprint(),request.spec.inputFingerprint(),Scope.FULL,binding.catalog()),binding,()->false);var original=MinutesCandidateGraphPlan.prepareReceipt(request.spec,request.input.actor().enterpriseId(),output,binding.catalog(),graph,request.input.budget(),request.taskId);var body=JdbcMinutesFactsReader.one(graph,Table.MINUTES_REVISION,original.bodyId());var set=JdbcMinutesFactsReader.one(graph,Table.ELEMENT_SET,original.setId());assertNull(body.nullableString("parent_id"));
  var d=graph.discovery();var root=new LinkedHashMap<>(d.root());root.put("minutes_revision_id",UUID.randomUUID().toString());var later=new MinutesGraphCapture.Graph(new MinutesGraphDiscovery.Discovery(d.meeting(),d.kind(),d.selected(),root,d.tables(),d.memberships(),d.identities(),d.selectors()),graph.rows(),graph.auxiliary());
  var replay=assertDoesNotThrow(()->MinutesCandidateGraphPlan.prepareReceipt(request.spec,request.input.actor().enterpriseId(),output,binding.catalog(),later,request.input.budget(),request.taskId));assertEquals(original.candidateId(),replay.candidateId());assertEquals(original.rows(body.number("revision"),set.number("revision")),replay.rows(body.number("revision"),set.number("revision")));
  for(String corrupt:List.of(body.string("id"),UUID.randomUUID().toString())){var cells=new ArrayList<>(body.cells());cells.set(Table.MINUTES_REVISION.index("parent_id"),ama.contract.MinutesContracts.cell(corrupt));var rows=new ArrayList<>(graph.rows());rows.set(rows.indexOf(body),new FullRow(Table.MINUTES_REVISION,cells));var bad=new MinutesGraphCapture.Graph(later.discovery(),rows,graph.auxiliary());assertThrows(Failure.class,()->MinutesCandidateGraphPlan.prepareReceipt(request.spec,request.input.actor().enterpriseId(),output,binding.catalog(),bad,request.input.budget(),request.taskId));}
 }
}
